llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "In healthy subjects, 5-hydroxyrofecoxib had an oral bioavailability of 14.0% after a 25 mg oral dose versus i.v., directly below the 20% threshold; this high-transfer human PK evidence supports low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "EM574, a complex oxygen-rich polycyclic lactone, showed an estimated human oral bioavailability of about 2%, indicating very low systemic exposure after oral dosing; its lactone-rich character is relevant to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "9-Nitrocamptothecin, a polycyclic lactone natural product, had very low and erratic absolute oral bioavailability in patients, consistent with dissolution-limited and incomplete absorption relevant to the query's lactone-rich scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Naringin, a highly oxygenated glycosylated polyphenol, had human oral bioavailability of only 5–9%, providing additional transferable evidence that such polar, poorly permeable natural products tend to fall below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Omadacycline, the highest-transfer analogue, showed an absolute oral bioavailability of 34.5% in healthy adults, above the 20% threshold; this is the main evidence favoring high bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the highest-transfer analogue omadacycline is orally bioavailable at 34.5%, the majority of transferable human PK evidence—including direct F values of 2–14% for structurally relevant lactone-rich and oxygenated polycyclics—supports low oral bioavailability (<20%) for the query. The consistent low-F direction across multiple high-transfer analogues outweighs the single high-F outlier.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Conflicting high-F evidence from omadacycline, the highest-transfer analogue.",
    "Transfer scores are model-derived and not structural-similarity scores, adding uncertainty to their biological interpretation.",
    "Exact chemical class and physicochemical properties of the query are not fully established from the SMILES alone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

